  ('von-wem-san-de-zwaa-tickets-san-des-unsrige', 'Von wem san de zwaa Tickets? San des unsrige?', '', '', '', 'Wiener Sprüche, die sitzen!', 'Von wem sind die zwei Tickets? Sind das die unsrigen?', '[{"kategorie": "wörtlich", "text": "\"Von wem sind die zwei Tickets? Sind die von uns?\"  2. Wem gehören diese beiden Tickets? Sind das etwa unsere?  3. Sind das eure Tickets oder doch unsrige?"}]'::jsonb, ''),
  ('des-hundal-muass-wem-ghean-owa-unsrigs-is-ned', 'Des Hundal muass wem ghean, owa unsrigs is ned!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das Hunderl muss jemandem gehören, aber das unsrige ist es nicht!', '[{"kategorie": "wörtlich", "text": "\"Das Hündchen muss jemandem gehören, aber unseres ist es nicht!\"  2. Zu wem gehört das Hündchen? Von uns ist es nicht!  3. Unser Hündchen ist das nicht, aber irgendwem muss es ja gehören!"}]'::jsonb, ''),
