  ('wachaua-marueuen', 'Wachaua Marüün', '', '', '', '', 'Wachauer Marille', '[{"kategorie": "wörtlich", "text": "\"Original Wachauer Marille g.U.\" (geschützte Ursprungsbezeichnung gemäß EU-Herkunftsschutz)"}, {"kategorie": "", "text": "\"Wachauer Marille\" ist eine geschützte Herkunftsbezeichnung für Marillen (Aprikosen) aus der [[Wachau]] in Niederösterreich, bekannt für ihr intensives Aroma und ihre hohe Qualität"}]'::jsonb, ''),
  ('wem-duachn-kakau-ziang', 'wem duachn Kakau ziang', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemanden durch den Kakao ziehen', '[{"kategorie": "wörtlich", "text": "\"jemanden lächerlich machen\""}, {"kategorie": "", "text": "\"jemanden auf die [[Schaufel]] nehmen\""}, {"kategorie": "", "text": "\"jemanden durch die [[Mangel]] drehen\""}]'::jsonb, 'Ma muass si sööwa duachn Kakau ziang kenna - schliisslich is des Leebm a aanzicha tragigkomischa Witz!'),
  ('ma-muass-si-soeoewa-duachn-kakau-ziang-kenna-schliisslich-is-des-leebm-a-aanzicha-tragigkomischa-witz', 'Ma muass si sööwa duachn Kakau ziang kenna - schliisslich is des Leebm a aanzicha tragigkomischa Witz!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Man muss sich selbst durch den Kakao ziehen können - schließlich ist das Leben ein einziger tragikomischer Witz!', '[{"kategorie": "wörtlich", "text": "\"Man sollte über sich selbst lachen können – schließlich ist das Leben ist ein einziges absurdes Theater!\"  2. Ein bisschen Selbstspott schadet nie – das Leben nimmt uns sowieso nicht ernst!  3. Wer sich selbst zu ernst nimmt, wird vom Leben ausgelacht!"}]'::jsonb, 'wem duachn Kakau ziang'),
  ('is-d-kua-hii-sois-kaeuwae-aa-hi-sei', 'Is d''Kua hii, sois Käuwä aa hi sei!', '', '', '', '', 'Ist die Kuh hin, soll das Kalbl auch hin sein!', '[{"kategorie": "", "text": "Da soll doch gleich alles zum Teufel fahren!  2. Jetzt ist ohnehin nichts mehr zu retten!  3. Jetzt ist eh schon alles [[wurscht]]!  4. Da soll doch gleich alles vor die Hunde gehen!"}]'::jsonb, ''),
  ('dea-passd-aufd-koeoewawoog', 'Dea passd aufd Kööwawoog!', '', '', '', '', 'Der passt auf die Kälberwaage!', '[{"kategorie": "scherzhaft für", "text": "\"Der muss mit einer Kälberwaage gewogen werden!\"  2. Der muss auf die Großviehwaage!  3. Den wiegt man besser mit einer Schwerlastwaage!"}]'::jsonb, ''),
  ('ea-hod-a-klans-kalaessl-und-dazua-zwa-faesche-ressl', 'Ea hod a klans Kalässl und dazua zwa fäsche Ressl!', '', '', '', '', 'Er hat ein kleines Kalessel und dazu zwei fesche Rösser!', '[{"kategorie": "wörtlich", "text": "\"Er besitzt einen kleinen Kutschwagen mitsamt zwei schönen Rössern!\"  2. Er hat eine kleine [[Kalesche]] mitsamt zwei schönen Zugpferden!"}]'::jsonb, ''),
  ('kalwaribeag-oostamoakd', 'Kalwaribeag-Oostamoakd', '', '', '', 'Wiener Prachtpalais und Prunkbauten', 'Kalvarienberg-Ostermarkt', '[{"kategorie": "allg.", "text": "traditioneller Wiener Ostermarkt mit Kunsthandwerksfokus, der alljährlich in der Fastenzeit vor Ostern am Kalvarienberg im 17. Wiener Gemeindebezirk ([[Hernals]]) stattfindet. Er gehört zu den ältesten und kulturell vielfältigsten Ostermärkten Wiens und verbindet religiös-historische Wurzeln mit zeitgenössischem Kunsthandwerk, Musik und Familienprogramm (Adresse: Kalvarienberggasse 33, 1170 Wien, Platz bei der [[Kalvarienbergkirche]])"}, {"kategorie": "", "text": "Der Markt geht auf die Wallfahrts- und Pilgertradition rund um die [[Kalvarienbergkirche]] (erbaut 1738–1740) zurück. Schon im 18. Jahrhundert kamen Gläubige zur Andacht und es entstand eine Markttradition mit religiösen Devotionalien, Fastenspeisen und später auch Kunsthandwerk. In den 1950er- bis 1970er-Jahren war der Markt sehr populär, verlor jedoch später an Bedeutung – wurde aber seit den 1990er-Jahren als Kunsthandwerksmarkt neu belebt"}, {"kategorie": "", "text": "Das Wahrzeichen des Kalvarienberg-Marktes ist der [[Baamkraxla]] (\"Baumkraxler\"), ein Kinderspielzeug, bestehend aus einem bunten kleinen Männchen, das durch die Schwerkraft auf einem Metallstab nach unten zuckelt, während eine Feder auf der anderen Seite des Stabes ein Glöckchen zum Bimmeln bringt"}, {"kategorie": "", "text": "Der \"Baamkraxla\" ist ein Spielzeug mit biblischer Vorgeschichte und erinnert laut Lukas-Evangelium an den kleinen Zachäus, der beim Einzug Jesu in Jericho vor 2000 Jahren auf einen Baum \"kraxelte\", damit er Jesus besser sehen konnte. Da blickte Jesus zu Zachäus empor und meinte zu ihm: „Zachäus, steig schnell herab, denn ich muss bis morgen in Deinem Haus bleiben!“, worauf der kleine Zachäus blitzschnell wieder vom Baum herunterkletterte und Jesus für eine Nacht bei sich zu Hause aufnahm."}]'::jsonb, ''),
  ('braune-kaumma', 'braune Kaumma', '', '', '', '', 'braune Kammer', '[{"kategorie": "", "text": "After, Poloch, [[Rosette]]"}, {"kategorie": "", "text": "Hintern, [[Arsch]], Gesäß"}]'::jsonb, ''),
  ('gwoschn-gschneizd-und-kampaed', 'gwoschn, gschneizd und kampäd', '', '', '', '', 'gewaschen, geschnäuzt und gekämmt', '[{"kategorie": "wörtlich", "text": "\"gewaschen, geschniegelt und gestriegelt\""}, {"kategorie": "scherzhaft für", "text": "wie aus dem Ei gepellt, [[wie]] aus dem Schachterl"}, {"kategorie": "", "text": "für einen besonderen Anlass fesch herausgeputzt, \"schick angezogen und durchgekämmt\", \"top gestylt\""}]'::jsonb, ''),
  ('auf-da-kantn-sei', 'auf da Kantn sei', '', '', '', '', 'auf der Kanten sein', '[{"kategorie": "wörtlich", "text": "\"auf Achse sein\""}, {"kategorie": "", "text": "auf Tour sein"}, {"kategorie": "", "text": "unterwegs sein"}, {"kategorie": "", "text": "\"die Gegend unsicher machen\""}]'::jsonb, ''),
  ('si-de-kantn-geem', 'si de Kantn geem', '', '', '', '', 'sich die Kanten geben', '[{"kategorie": "", "text": "die Sau rauslassen"}, {"kategorie": "", "text": "es ordentlich krachen lassen"}, {"kategorie": "", "text": "feiern bis zum Umfallen"}, {"kategorie": "", "text": "die Puppen tanzen lassen"}, {"kategorie": "", "text": "[[einen]] Mulatschag machen"}]'::jsonb, ''),
  ('kapores-gee', 'kapores gee', '', '', '', '', 'kapores gehen', '[{"kategorie": "wörtlich", "text": "\"kaputt gehen\" (vom jiddischen [[kapores]]=\"kaputt\")"}, {"kategorie": "", "text": "sterben, das Zeitliche segnen, [[a]] Bankerl reißn"}]'::jsonb, ''),
  ('kapores-schloong', 'kapores schloong', '', '', '', '', 'kapores schlagen', '[{"kategorie": "wörtlich", "text": "\"kaputt schlagen\" (vom jiddischen \"kapores shlogn\" = \"das Schlachten von Hühnern als Sühne- beziehungsweise Versöhnungsopfer\")"}, {"kategorie": "fig.", "text": "jemanden oder etwas kurz und klein schlagen, in tausend Stücke schlagen, zu Kleinholz verarbeiten"}]'::jsonb, ''),
  ('i-ziag-mei-koppn-vua-dia', 'I ziag mei Koppn vua dia!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich ziehe meine Kappe vor dir!', '[{"kategorie": "wörtlich", "text": "\"Ich ziehe meinen Hut vor dir!\"  2. \"Ich verneige mich vor dir!\"  3. \"Ehre, wem Ehre gebührt!\"  4. \"Da kann man nur den Hut ziehen!\""}]'::jsonb, ''),
  ('dazoeoe-ma-ned-de-koppn-is-von-allaa-owegaungan-waeu-sunst-bin-i-da-haeuliche-oeoedruck', 'Dazöö ma ned, de Koppn is von allaa owegaungan - wäu sunst bin I da häuliche Öödruck!', '', '', '', 'Wiener Mechaniker-Slang', 'Erzähl mir nicht, dass die Kappe von alleine runtergegangen ist - weil sonst bin ich der heilige Öldruck!', '[{"kategorie": "wörtlich", "text": "\"Erzähl mir nicht, die Kappe sei von alleine runtergegangen - weil sonst bin ich der heilige Öldruck!\"  2. Sag ja nicht, dass sich die Schutzkappe von alleine gelöst hat - denn sonst sag ich dir, dass ich David Copperfield bin!  3. Red keinen Schmarren - wenn die Schutzkappe von selbst abgeht, flöge auch die Zylinderkopfdichtung freiwillig raus!"}]'::jsonb, ''),
  ('den-eiaschuss-haed-da-gooli-mid-da-koppn-faungan-kenna', 'Den Eiaschuss häd da Gooli mid da Koppn faungan kenna!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Diesen Eierschuss hätte der Goalie mit der Kappe fangen können!', '[{"kategorie": "wörtlich", "text": "\"Dieses harmlose Schüsschen hätte der Tormann mit der Mütze fangen können!\"  2. Diesen Rohrkrepierer hätte ein Blinder mit ’nem Krückstock gefangen!  3. Das war ein Schüsschen für den Streichezoo – sichere Beute für den Keeper!"}]'::jsonb, ''),
  ('den-kindafreindeschuss-haed-da-gooli-aa-min-kappal-faungan-kenna', 'Den Kindafreindeschuss häd da Gooli aa min Kappal faungan kenna!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Diesen Kinderfreundeschuss hätte der Goalie auch mit seinem Käppi fangen können!', '[{"kategorie": "wörtlich", "text": "\"Dieses harmlose Schüsschen hätte der Tormann mit der Mütze fangen können!\"  2. Diesen Rohrkrepierer hätte ein Blinder mit ’nem Krückstock gefangen!  3. Das war ein Schüsschen für den Streichezoo – sichere Beute für den Keeper!"}]'::jsonb, ''),
  ('wuevueue-kappaen-hod-a-bluadreal-eigentlich-offnboa-aans-mea-ois-i-haend-hob', 'Wüvüü Kappän hod a Bluadreal eigentlich - offnboa aans mea ois I Händ hob!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Wie viele Kappen hat ein Blutröhrchen eigentlich - offenbar eine mehr als ich Hände hab!', '[{"kategorie": "wörtlich", "text": "\"Wie viele Verschlusskappen hat ein Blutröhrchen eigentlich - scheinbar um eine mehr als ich Hände hab!\"  2. Das Blutröhrchen hat so viele Verschlusskappen, ich brauch bald ’nen Assistenten nur fürs Auf- und Zudrehen!  3. Das Blutröhrchen hat so viele Verschlusskappen - da brauchst bald ein Drehbuch, um die Reihenfolge beim Abnehmen zu kapieren!"}]'::jsonb, ''),
  ('des-kappal-auf-sein-schaeaedl-is-wia-augwochsn-i-glaub-dea-duuschd-sogoa-damit', 'Des Kappal auf sein Schäädl is wia augwochsn - I glaub, dea duuschd sogoa damit!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Das Kapperl auf seinem Schädel ist wie angewachsen - ich glaub, der duscht sogar damit!', '[{"kategorie": "wörtlich", "text": "\"Das Käppi auf seinem Kopf ist wie festgewachsen - ich glaub, der duscht sogar damit!\"  2. Seine Baseballkappe ist quasi angewachsen - wahrscheinlich duscht er sogar damit!  3. Ohne sein Käppchen fühlt er sich nackt - ich glaub'', er schläft sogar damit!"}]'::jsonb, ''),
  ('setz-da-s-kappal-auf-bevua-da-da-letzte-rest-vom-hian-aa-no-eifriad', 'Setz da s''Kappal auf, bevua da da letzte Rest vom Hian aa no eifriad!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Setz dir das Kapperl auf, bevor dir der letzte Rest vom Hirn auch noch einfriert!', '[{"kategorie": "wörtlich", "text": "\"Zieh dir ''ne Mütze über''n Kopf, bevor dir der letzte Rest vom Hirn auch noch wegfriert!\"  2. Setz dir dein Käppi auf, bevor dein Oberstübchen ganz vereist!  3. Setz dein Mützchen auf, bevor deine Restintelligenz zum Frosthirn verkommt!"}]'::jsonb, ''),
  ('du-muassd-s-kappal-von-dem-gloosweckn-easchd-aufschraufn-waunnsd-draus-trinkn-wueuesd-du-hianeedal', 'Du muassd s''Kappal von dem Gloosweckn easchd aufschraufn, waunnsd draus trinkn wüüsd, du Hianeedal!', '', '', '', 'Wiener Würstelstandjargon', 'Du musst das Kapperl von dem Glaswecken erst aufschrauben, wenn du daraus trinken willst, du Hirnederl!', '[{"kategorie": "wörtlich", "text": "\"Du musst die Verschlusskappe der Bierglasflasche erst aufdrehen, wenn du daraus trinken willst, du Dumpfbacke!\"  2. Du musst die Bierflasche erst aufschrauben, sonst kommt da nix raus, du Dillo!  3. Das Käppchen auf der Bierflasche lässt sich aufdrehen, du Dolm – also runter damit und dann Prost!"}]'::jsonb, ''),
  ('des-kappae-aum-plutza-is-sei-marknzeichn-des-troogda-sogoa-zum-aunzug', 'Des Kappä aum Plutza is sei Marknzeichn - des troogda sogoa zum Aunzug!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das Käppchen auf''m Plutzer ist sein Markenzeichen - das trägt er sogar zum Anzug!', '[{"kategorie": "wörtlich", "text": "\"Das Käppi auf''m Kopf ist sein Markenzeichen - das trägt er sogar zum Anzug!\"  2. \"Sein Käppi gehört einfach zu ihm – selbst wenn er sich in Schale wirft, trägt er es wie eine Krone auf dem Kopf!\"  3. \"Das Käppi ist sein Stil-Statement – auch im Anzug trägt er es auf seinem Kopf!\""}]'::jsonb, ''),
  ('wem-aufd-koppn-schdeing', 'wem aufd Koppn schdeing', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem auf die Kappe steigen', '[{"kategorie": "wörtlich", "text": "\"jemandem auf den Kopf steigen\""}, {"kategorie": "", "text": "\"jemandem auf den Leib rücken\""}, {"kategorie": "", "text": "\"jemanden zur Rechenschaft ziehen\""}, {"kategorie": "", "text": "\"auf jemandes Nerven reiten\""}, {"kategorie": "", "text": "[[jemandem]] aufs Dach steigen"}]'::jsonb, 'Du bisd a vüü z''guada Lootsch - loss da ned von an jeedn aufd Koppn schdeing!'),
  ('du-bisd-a-vueue-z-guada-lootsch-loss-da-ned-von-an-jeedn-aufd-koppn-schdeing', 'Du bisd a vüü z''guada Lootsch - loss da ned von an jeedn aufd Koppn schdeing!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Du bist ein viel zu guter Latsch - lass dir nicht von jedem auf die Kappe steigen!', '[{"kategorie": "wörtlich", "text": "\"Du bist ein viel zu gutmütiger Kerl - lass dir nicht von jedem auf den Kopf steigen!\"  2. Du bist ein viel zu netter Typ - lass nicht zu, dass sie dir alle auf den Nerven herumreiten!  3. Du bist ein herzensguter Mensch - aber lass dir doch nicht alles gefallen!"}]'::jsonb, 'wem aufd Koppn schdeing'),
  ('wem-aufs-doch-schdeing', 'wem aufs Doch schdeing', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem aufs Dach steigen', '[{"kategorie": "wörtlich", "text": "\"jemandem auf den Kopf steigen\""}, {"kategorie": "", "text": "\"jemandem auf den Leib rücken\""}, {"kategorie": "", "text": "\"jemanden zur Rechenschaft ziehen\""}, {"kategorie": "", "text": "\"auf jemandes Nerven reiten\""}, {"kategorie": "", "text": "[[wem aufd Koppn schdeing]]"}]'::jsonb, ''),
  ('de-linke-haed-ma-uns-schboan-kenna-jetzd-wiad-uns-da-kaadi-aufs-doch-schdeing', 'De Linke häd ma uns schboan kenna - jetzd wiad uns da Kaadi aufs Doch schdeing!', '', '', '', 'Wiener Gaunersprache', 'Diese Linke hätten wir uns sparen können - jetzt wird uns der Kadi aufs Dach steigen!', '[{"kategorie": "wörtlich", "text": "\"Dieses linke Ding hätten wir uns sparen können - jetzt wird uns der Richter aufs Dach steigen!\"  2. Diese miese Tour hätten wir uns sparen können – jetzt wird uns der Richter gehörig die Leviten lesen!  3. Diese krumme Nummer war echt überflüssig – dafür wird uns der Richter jetzt ordentlich den Kopf waschen!"}]'::jsonb, 'wem aufs Doch schdeing'),
  ('wem-aufd-koppn-gee', 'wem aufd Koppn gee', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem auf die Kappen gehen', '[{"kategorie": "wörtlich", "text": "\"jemandem auf die [[Kappe]] gehen\" (\"Kappe\" steht hier sinnbildlich für \"Kopf\" → = auf den Kopf gehen → jemanden nerven)"}, {"kategorie": "", "text": "\"jemandem auf die Nerven gehen\""}, {"kategorie": "", "text": "\"jemandem auf den Geist gehen\""}, {"kategorie": "", "text": "[[jemandem auf den Wecker gehen]]"}, {"kategorie": "", "text": "[[wem aum Zwickl gee]]"}, {"kategorie": "", "text": "[[wem aum Sock gee]]"}, {"kategorie": "", "text": "[[wem aufd Eia gee]]"}, {"kategorie": "", "text": "[[wem aum Zaaga gee]]"}, {"kategorie": "", "text": "[[wem aum Schlauch gee]]"}, {"kategorie": "", "text": "[[wem aum Haumma gee]]"}, {"kategorie": "", "text": "[[wem aum Oasch gee]]"}]'::jsonb, ''),
  ('mia-geed-des-uandlich-aufd-koppn-dass-imma-i-ois-ausboodn-muass', 'Mia geed des uandlich aufd Koppn, dass imma I ois ausboodn muass!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Mir geht das ordentlich auf die Kappe, dass immer ich alles ausbaden muss!', '[{"kategorie": "wörtlich", "text": "\"Mir geht das gehörig auf den Geist, dass immer ich alles ausbaden muss!\"  2. Es nervt mich total, dass immer ich den Kopf hinhalten muss!  3. Es geht mir tierisch auf die Nerven, dass ich ständig den Karren aus dem Dreck ziehen muss!"}]'::jsonb, 'wem aufd Koppn gee'),
  ('des-geed-auf-mei-koppn', 'Des geed auf mei Koppn!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das geht auf meine Kappe!', '[{"kategorie": "wörtlich", "text": "\"Dafür übernehme ich die Verantwortung!\"  2. \"Ich nehme die ganze Schuld dafür auf mich!\"  3. \"Ich allein bin dafür verantwortlich!\" [In früheren Jahrhunderten (besonders im späten Mittelalter) war die Kappe – egal ob Helm, Mütze, Hut oder Barett – ein Symbol der Person oder ihrer Rolle. „Etwas geht auf meine Kappe“ bedeutete wörtlich: → Etwas wird mir zugerechnet, es „landet auf meinem Kopf“, also auf mir selbst als Person]"}]'::jsonb, ''),
  ('si-min-kappae-faunga-lossn', 'si min Kappä faunga lossn', '', '', '', 'Wiener Gaunersprache', 'sich mit dem Kappl fangen lassen', '[{"kategorie": "wörtlich", "text": "\"sich wie ein Schulbub einfangen lassen\""}, {"kategorie": "fig.", "text": "\"sich wie ein Amateur einsacken lassen\""}, {"kategorie": "", "text": "sich wie ein Anfänger über den Tisch ziehen lassen"}]'::jsonb, 'Dea hod si von d''Kiiwara min Kappä faungan lossn, dass echt schoo peinlich is!'),
  ('dea-hod-si-von-d-kiiwara-min-kappae-faungan-lossn-dass-echt-schoo-peinlich-is', 'Dea hod si von d''Kiiwara min Kappä faungan lossn, dass echt schoo peinlich is!', '', '', '', 'Wiener Gaunersprache', 'Der hat sich von den Kieberern mit''m Kappl fangen lassen, dass es echt schon peinlich ist!', '[{"kategorie": "wörtlich", "text": "\"Der ließ sich von den Bullen quasi im Vorbeigehen einsacken - peinlicher geht''s wohl nicht!\"  2. Sich so billig erwischen zu lassen – da muss man sich als Ganove fremdschämen!  3. Der Trottel hat sich erwischen lassen wie ein Kind mit Schokolade im Gesicht!"}]'::jsonb, ''),
  ('de-kappalfettn-muass-aussegschniidn-wean-bevua-ma-s-gansl-fueued-waeu-sunsd-schmeckd-de-sooss-ranzich', 'De Kappalfettn muass aussegschniidn wean, bevua ma s''Gansl füüd, wäu sunsd schmeckd de Sooss ranzich!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Die Kapperlfetten muss rausgeschnitten werden, bevor man die Gans füllt, weil sonst schmeckt die Soße ranzig!', '[{"kategorie": "wörtlich", "text": "\"Der Fetthöcker am Bürzel muss rausgeschnitten werden, bevor man die Gans füllt, weil sonst schmeckt die Soße tranig!\"  2. Vor dem Füllen der Gans muss das Drüsenfett am Bürzel entfernt werden, sonst bekommt die Soße einen unangenehmen Beigeschmack!  3. Bevor man die Gans füllt, muss das Schwimmfett am Bürzel herausgeschnitten werden, da es sonst den Bratensaft ungenießbar macht!"}]'::jsonb, ''),
  ('si-hod-imma-iagendwoeche-kaprizn', 'Si hod imma iagendwöche Kaprizn!', '', '', '', '', 'Sie hat immer irgendwelche Kaprizen!', '[{"kategorie": "", "text": "Sie hat immer irgendwelche Anwandlungen!  2. Sie hat ständig ihre Marotten!  3. Sie hat immer irgendwelche Flausen im Kopf!  4. Sie macht ständig irgendwelche Faxen!"}]'::jsonb, ''),
  ('kaprizia-di-ned-so', 'Kaprizia di ned so!', '', '', '', '', 'Kapriziere dich nicht so!', '[{"kategorie": "", "text": "Spiel dich nicht so auf!  2. Stell dich nicht so an!  3. Sei nicht so stur!  4. Zick nicht so herum!  5. Zier dich nicht so!"}]'::jsonb, ''),
  ('si-kaprizian', 'si kaprizian', '', '', '', '', 'sich kaprizieren', '[{"kategorie": "wörtlich", "text": "\"sich aufspielen\" (vom französischen \"caprice\"=\"Laune\")"}, {"kategorie": "", "text": "sich wichtigmachen, sich aufplustern, sich in den Vordergrund drängen 3. sich zieren, herumzicken, Faxen machen"}]'::jsonb, ''),
  ('si-auf-wos-kaprizian', 'si auf wos kaprizian', '', '', '', '', 'sich auf etwas kaprizieren', '[{"kategorie": "wörtlich", "text": "\"sich auf etwas versteifen\" (vom französischen \"caprice\"=\"Laune\" bzw. \"Eigensinn\")"}, {"kategorie": "", "text": "sich in etwas verbeißen, eisern beharren auf etwas, \"etwas zum persönlichen Kreuzzug machen\", an etwas unnachgiebig festhalten"}]'::jsonb, ''),
  ('kaput', 'Kapút', '', '', '', '', 'Kapút', '[{"kategorie": "wörtlich, Betonung auf 2. Silbe", "text": "\"Mantel\" (vom italienischen \"cappotto\"=\"Mantel\")"}, {"kategorie": "", "text": "dicker Mantel, Wintermantel, auch: Soldatenmantel"}]'::jsonb, ''),
  ('ziag-dein-wattiadn-kaput-au-sunst-wiad-da-koid', 'Ziag dein wattiadn Kapút au, sunst wiad da koid!', '', '', '', '', 'Zieh deinen wattierten Kapút an, sonst wird dir kalt!', '[{"kategorie": "", "text": "Zieh deinen gefütterten Mantel an, sonst wird dir kalt!  2. Schlupf in deinen dicken Wintermantel, sonst wirst du frieren!"}]'::jsonb, ''),
  ('min-voin-karacho', 'min voin Karacho', '', '', '', '', 'mit vollem Karacho', '[{"kategorie": "wörtlich", "text": "\"mit komplett heraushängendem Pimmel\" (vom spanischen \"a carajo sacado\"=\"mit aus der Hose herausgeholtem Pimmel\")"}, {"kategorie": "scherzhaft für", "text": "mit einem Affenzahn, mit Vollgas, [[mit]] einem Ur-Tender, [[mit]] einem Mordshadern, [[volle Wäsch]], [[volle Post]]"}]'::jsonb, ''),
  ('ea-is-min-voin-karacho-iwad-autobaun-pledad', 'Ea is min voin Karacho iwad Autobaun pledad!', '', '', '', '', 'Er ist mit vollem Karacho über die Autobahn gepledert!', '[{"kategorie": "", "text": "Er ist [[volle]] Wäsch über die Autobahn gebrettert!  2. Er ist in einem Höllentempo über die Autobahn gefegt!  3. Er ist mit Vollgas über die Autobahn geheizt!"}]'::jsonb, ''),
