  ('des-is-von-do-nuara-kotznschbrung', 'Des is von do nuara Kotznschbrung!', '', '', '', '', 'Das ist von hier nur ein Katzensprung', '[{"kategorie": "wörtlich", "text": "Das ist von hier nur einen Katzensprung entfernt!  2. Das ist gleich um die Ecke!  3. Das ist von hier nur einen Steinwurf entfernt!"}]'::jsonb, ''),
